# Draw readable, editable concept plans in SVG; image assets are never substituted.
def text(x,y,label,size=15,fill='#254231',anchor='start'):
    return f'<text x="{x}" y="{y}" font-family="Arial,sans-serif" font-size="{size}" fill="{fill}" text-anchor="{anchor}">{e(label)}</text>'
def tree(x,y,r=46):
    return f'<circle cx="{x+5}" cy="{y+7}" r="{r}" fill="#203c2512"/><circle cx="{x}" cy="{y}" r="{r}" fill="#91a47a" stroke="#637b57" stroke-width="1.5"/><circle cx="{x-7}" cy="{y-8}" r="{r*.7}" fill="#acba94" opacity=".5"/><path d="M{x} {y+r*.7}V{y-r*.6}m0 {r*.5}l{-r*.4} {-r*.35}m{r*.4} {r*.6}l{r*.4} {-r*.35}" stroke="#667958" stroke-width="1.5" fill="none"/>'
