CSS='''*{box-sizing:border-box}body{margin:0;background:#0e211b;color:#243b2e;font-family:Arial,sans-serif}h1,h2,h3,p{margin:0}h1,h2,h3{font-family:Georgia,serif;font-weight:400}a{color:inherit}.slide{position:relative;width:1440px;height:900px;margin:35px auto;background:#f4f1e8;overflow:hidden;break-after:page}.inner{height:100%;padding:68px 80px 82px}.eyebrow{font-size:11px;letter-spacing:3.2px;text-transform:uppercase;margin-bottom:25px;color:#778069}.slide h1{font-size:76px;line-height:1.04;letter-spacing:-2.5px;white-space:pre-line;margin-bottom:28px}.slide p{font-size:21px;line-height:1.65;color:#68715f}.folio{position:absolute;bottom:26px;left:40px;right:40px;display:flex;justify-content:space-between;align-items:center;font-size:9px;letter-spacing:2px;z-index:4;text-transform:uppercase;color:#717c68}.folio b{font-weight:400;color:#9b8267}.split-layout{display:grid;grid-template-columns:42% 58%;height:100%}.copy{padding:72px 62px 86px 72px}.copy h1{font-size:61px}.copy p{font-size:19px}.split-layout>img{width:100%;height:100%;object-fit:cover}.copy ul{margin-top:30px;padding-left:18px;font-size:15px;line-height:1.65}.copy li{padding:6px 0}.cover,.hero{background:#10271e;color:#fff}.cover>img,.hero>img{width:100%;height:100%;object-fit:cover}.cover:after,.hero:after{position:absolute;inset:0;content:"";background:linear-gradient(0deg,#071a13d9,transparent 78%)}.cover .overlay,.hero .overlay{position:absolute;left:78px;bottom:86px;z-index:2;max-width:1040px}.cover h1{font-size:120px;letter-spacing:-5px}.hero h1{font-size:80px}.cover p,.hero p{color:#eeeede;max-width:1000px;font-size:20px}.cover .eyebrow,.hero .eyebrow,.cover .folio,.hero .folio{color:#e7e8d8}.cover .folio b,.hero .folio b{color:#d5c6a4}.board-layout{height:100%;display:grid;grid-template-columns:35% 65%;gap:32px;padding:70px 64px 80px}.board-layout h1{font-size:62px}.board-layout p{font-size:19px}.board-layout img{width:100%;height:680px;object-fit:contain;align-self:center}.plan .split-layout{grid-template-columns:31% 69%}.plan .copy{padding:68px 28px 75px 52px}.plan .copy h1{font-size:53px}.plan .copy p{font-size:17px}.plan img{object-fit:contain;background:#f4f1e8}.principles{background:#1a342a;color:#eceade}.principles p{color:#c1cab8}.principles .eyebrow,.principles .folio{color:#a7b899}.points{display:grid;grid-template-columns:1fr 1fr;gap:25px 60px;margin-top:48px}.points div{border-top:1px solid #9dab8c66;padding-top:20px;font-size:24px;line-height:1.4}.points small{display:block;color:#9da68e;font-size:12px;margin-bottom:13px}.palette .swatches{display:flex;margin-top:42px;height:330px}.swatch{flex:1;display:flex;flex-direction:column;justify-content:flex-end;padding:30px 22px;font-size:17px}.swatch small{font-size:11px;letter-spacing:2px;margin-top:12px}.swatch:nth-last-child(-n+3){color:#fff}.plants table,.budget table{border-collapse:collapse;width:100%;font-size:16px;margin-top:24px}td,th{padding:12px 10px;border-bottom:1px solid #cdd0bf}th{text-align:left;font-size:10px;letter-spacing:1.5px;color:#77816b;text-transform:uppercase}.plants .inner>p{font-size:18px}.plants h1{font-size:64px}.plants td:last-child{font-size:14px}.budget h1{font-size:59px;margin-bottom:18px}.budget .inner{padding-top:45px}.budget .inner>p{font-size:17px;line-height:1.5}.budget td{padding:8px 10px;font-size:15px}.budget td:last-child{text-align:right}.budget .total{display:flex;justify-content:space-between;background:#274834;color:#edf0de;padding:18px 22px;margin-top:22px;font-size:28px}.cards{display:flex;gap:26px;margin-top:44px}.card{flex:1;background:#e5e7da;padding:30px;min-height:245px}.card h3{font-size:34px;line-height:1.15}.card strong{display:block;font-size:38px;font-weight:400;margin:22px 0;color:#61734f}.card p{font-size:18px}.timeline-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:36px;margin-top:35px}.timeline-grid article{border-top:2px solid #869776;padding-top:18px}.timeline-grid h3{font-size:29px;margin:12px 0}.timeline-grid p{font-size:17px}.timeline-grid small{font-size:12px;letter-spacing:1px;color:#7a8968}.timeline h1{font-size:64px}.timeline .inner>p{font-size:19px}.hierarchy h1{font-size:64px}.tree{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin-top:30px}.tree article{background:#e5e7da;padding:26px;font-size:20px;line-height:1.7}.tree h3{font-size:30px;margin-bottom:14px}.child{border-left:1px solid #869379;margin-left:14px;padding-left:20px}.tree small{font-size:15px}.toolbar{position:fixed;right:18px;bottom:14px;display:flex;gap:20px;align-items:center;background:#f4f1e8;color:#243b2e;border-radius:30px;padding:13px 20px;font-size:12px;z-index:10;box-shadow:0 3px 25px #0003}.toolbar button{border:0;background:none;color:inherit;font:inherit;cursor:pointer}.toolbar a{text-decoration:none}@media screen and (max-width:1440px){.slide{width:100vw;height:62.5vw;margin:15px auto}.slide>*{zoom:var(--scale,1)}}@media print{@page{size:1440px 900px;margin:0}body{background:#fff}.slide{margin:0}.toolbar{display:none}}
'''
def img(s):return f'<img src="assets/{s["image"]}.{"svg" if s["image"] in manifest["plans"] else "webp"}" alt="{e(s["title"].replace(chr(10)," "))} — fictional garden concept">'
def content(s):
    head=f'<div class="eyebrow">{e(s["subtitle"])}</div><h1>{e(s["title"])}</h1>';desc=f'<p>{e(s["body"])}</p>';kind=s['kind']
    if kind in ('cover','hero'):return img(s)+f'<div class="overlay">{head}{desc}</div>'
    if kind=='board':return f'<div class="board-layout"><div>{head}{desc}</div>{img(s)}</div>'
    if s['image']:
        pts='<ul>'+''.join(f'<li>{e(x)}</li>' for x in s['points'])+'</ul>' if s['points'] else ''
        return f'<div class="split-layout"><div class="copy">{head}{desc}{pts}</div>{img(s)}</div>'
    extra=''
    if s['points']:extra='<div class="points">'+''.join(f'<div><small>{n:02d}</small>{e(x)}</div>' for n,x in enumerate(s['points'],1))+'</div>'
    if kind=='palette':extra='<div class="swatches">'+''.join(f'<div class="swatch" style="background:{c}">{label}<small>{c.upper()}</small></div>' for c,label in zip(manifest['theme']['colors'],['Chalk stone','Weathered copper','Meadow green','Dusk violet','Forest shadow']))+'</div>'
    if kind=='plants':extra='<table><tr><th>Layer</th><th>Candidate direction</th><th>Character</th></tr>'+''.join(f'<tr><td>{r[0]} / {e(r[2])}</td><td>{e(r[1])}</td><td>{e(r[4])}</td></tr>' for r in planting)+'</table>'
    if kind=='budget':
        rs=[r for r in budget if not r['included'] and not r['optional'] and r['kind']!='unknown']
        extra='<table><tr><th>Package</th><th>Basis</th><th>Investment incl. assumed VAT</th></tr>'+''.join(f'<tr><td>{e(r["label"])}</td><td>{"Allowance" if r["kind"]=="estimate" else "Fictional quote"}</td><td>{money(r["amount"]) if r["amount"] is not None else money(r["min_amount"])+"–"+money(r["max_amount"])}</td></tr>' for r in rs)+'</table><div class="total"><span>Known investment range</span><span>€213,400–€221,400</span></div>'
    if kind in ('options','scenes'):
        cards=[('Premium furniture','+ €8,000','Upgrade teak, textiles and the dining selection. Base furniture remains €14,500.'),('Outdoor kitchen','+ €12,800','An additional pavilion subquote. Shown in the imagery; off in the base budget.'),('Rainwater storage','+ €6,400','An additional drainage subquote, subject to site feasibility.')] if kind=='options' else [('Welcome','01','A clear arrival and a soft pavilion glow. Let the water hold the reflections.'),('Gather','02','Dining and task light where people sit and cook, with the garden behind in shadow.'),('Unwind','03','A quieter path scene and a timed transition toward darkness.')]
        extra='<div class="cards">'+''.join(f'<article class="card"><h3>{a}</h3><strong>{b}</strong><p>{c}</p></article>' for a,b,c in cards)+'</div>'
    if kind=='timeline':extra='<div class="timeline-grid">'+''.join(f'<article><small>{b}</small><h3>{c}</h3><p>{d}</p></article>' for a,b,c,d in programme)+'</div>'
    if kind=='hierarchy':extra='<div class="tree"><article><h3>Terra Forma / €64,000</h3><div class="child">Ground Atelier / €18,000 included</div><div class="child">Raincraft / €12,000 included</div><div class="child">Stone & Line / €34,000 included<div class="child">Quarry North / €19,500 included</div></div><small>Stone supply remains inside both parent totals.</small></article><article><h3>Timber Field / €32,000</h3><div>Timber and fitting / €23,000</div><div class="child">Frame Studio / €9,000 included</div><br><div>+ Kitchen option / €12,800</div><small>Additional, not included in the pavilion price.<br>Raincraft storage option adds a separate €6,400.</small></article></div>'
    return f'<div class="inner">{head}{desc}{extra}</div>'
body=''.join(f'<section class="slide {s["kind"]}" id="{s["key"]}" aria-label="Slide {i}: {e(s["title"])}">{content(s)}<footer class="folio"><span>STILLWATER / LANDSCAPE STUDIO</span><b>FICTIONAL DEMO · AI CONCEPT IMAGERY</b><span>{i:02d} / {len(slides):02d}</span></footer></section>' for i,s in enumerate(slides,1))
js='''<script>const slides=[...document.querySelectorAll('.slide')];let current=0;const o=new IntersectionObserver(entries=>{for(const x of entries)if(x.isIntersecting){current=slides.indexOf(x.target);document.querySelector('#counter').textContent=`${current+1} / ${slides.length}`;}},{threshold:.55});slides.forEach(x=>o.observe(x));function move(n){current=Math.max(0,Math.min(slides.length-1,current+n));slides[current].scrollIntoView({behavior:'smooth'});}document.querySelector('#prev').onclick=()=>move(-1);document.querySelector('#next').onclick=()=>move(1);document.querySelector('#full').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();document.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','PageDown','PageUp'].includes(e.key)){e.preventDefault();move(['ArrowRight','PageDown'].includes(e.key)?1:-1);}});function scale(){document.documentElement.style.setProperty('--scale',Math.min(1,innerWidth/1440))}scale();addEventListener('resize',scale);</script>'''
(OUT/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stillwater Garden — A landscape for a slower life</title><style>'+CSS+'</style><body>'+body+f'<nav class="toolbar" aria-label="Presentation controls"><button id="prev" aria-label="Previous slide">←</button><span id="counter">1 / {len(slides)}</span><button id="next" aria-label="Next slide">→</button><button id="full">Fullscreen</button><a href="{manifest["pdf"]}">PDF</a><a href="supplier-index.html">Project pack</a></nav>'+js+'</body></html>')

DOC='''@page{size:A4;margin:16mm}*{box-sizing:border-box}body{font:12px/1.35 Arial,sans-serif;color:#263e30;max-width:740px;margin:36px auto}h1,h2{font-family:Georgia,serif;font-weight:400}h1{font-size:32px;margin:12px 0 4px}h2{font-size:18px;margin-top:14px;break-after:avoid}.tag{font-size:10px;letter-spacing:2px;text-transform:uppercase;color:#6e7f61}.banner{background:#e9ecdf;padding:11px 14px;margin:14px 0;border-left:3px solid #6e7f61}.meta{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:12px 0}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #cbd1be;text-align:left}th{font-size:10px;text-transform:uppercase;letter-spacing:1px}td:last-child{text-align:right}.total{background:#244432;color:#fff;display:flex;justify-content:space-between;padding:14px 18px;font-size:22px}footer{font-size:10px;color:#728165;border-top:1px solid #cbd1be;padding-top:10px;margin-top:12px}a{color:#3a643f}@media print{body{margin:0}}'''
def document(title,body):return f'<!doctype html><html lang="en"><meta charset="utf-8"><title>{e(title)}</title><style>{DOC}</style><body>{body}</body></html>'
for ref,vendor,role,key,lines,lead,exclusions in quotes:
    total=sum(x[1] for x in lines);net=round(total/1.21,2);tax=round(total-net,2);r=next(x for x in budget if x['key']==key)
    body=f'<div class="tag">{e(role)} / Fictional supplier</div><h1>{e(vendor)}</h1><p>{vendor.lower().replace(" ",".").replace("&", "and")}@example.test</p><div class="banner"><strong>FICTIONAL DEMO QUOTATION — NOT A COMMERCIAL OFFER</strong><br>Created for Stillwater Garden. No real supplier has issued this document.</div><div class="meta"><div><strong>Prepared for</strong><br>Mira & Sebastiaan de Wilde (fictional)<br>Stillwater Garden / Veluwe, Netherlands<br>Via Stillwater Landscape Studio</div><div><strong>Reference</strong> {ref}<br><strong>Date</strong> 18 September 2026<br><strong>Illustrative validity</strong> 30 days<br><strong>Currency</strong> EUR</div></div><h2>{e(r["label"])}</h2><table><tr><th>Package scope</th><th>Amount incl. assumed VAT</th></tr>'+''.join(f'<tr><td>{e(label)}</td><td>{money(v)}</td></tr>' for label,v in lines)+f'</table><div class="total"><span>{"Base allowance" if key=="furniture" else "Package total"}</span><strong>{money(total)}</strong></div><p>Illustrative net €{net:,.2f} + assumed 21% VAT €{tax:,.2f} = €{total:,.2f}. Uniform fictional VAT assumption for demo arithmetic.</p><h2>Relationship to the project budget</h2><p>{e(r["note"])}</p><h2>Programme & commercial assumptions</h2><p>{e(lead)} Payment example: 40% on order, 40% before delivery, 20% after handover. No payment is requested. Final quantities and suitability follow site assessment.</p><h2>Exclusions & qualifications</h2><p>{e(exclusions)}</p><footer>STILLWATER GARDEN / {ref} / Fictional names and figures. No signature, registration number or bank details. Not for purchasing or construction.</footer>'
    (OUT/'suppliers'/f'{ref}.html').write_text(document(ref+' / '+vendor,body))
scope='''<div class="tag">Stillwater Garden / Scope schedule / 18 September 2026</div><h1>A clear foundation.</h1><div class="banner">FICTIONAL DEMO DOCUMENT / Illustrative project assumptions, not a contract.</div><h2>Included in the known investment</h2><p>Landscape construction; pavilion; planting; decorative reflecting pool; lighting; furniture allowance; productive garden; landscape design; first-year establishment care; and an €18,000 client-held contingency. Base selection €213,400; premium furniture €221,400. All figures are fictional and include uniformly assumed 21% VAT for demonstration arithmetic.</p><h2>Included subquotes</h2><p>Terra Forma €64,000 includes Ground Atelier €18,000, Raincraft €12,000 and Stone & Line €34,000. Stone & Line includes Quarry North €19,500. Timber Field €32,000 includes Frame Studio €9,000. Included subquotes are never added again.</p><h2>Options and unknowns</h2><p>Outdoor kitchen €12,800 is additional to the pavilion. Rainwater storage €6,400 is additional to drainage, even though drainage itself is included in the main contract. Both options are off in the base budget. Premium furniture adds €8,000. All selections together total €240,600. Exceptional or contaminated ground conditions remain unknown and are excluded from every stated total.</p><h2>Package boundaries</h2><p>General paths, terraces and lounge masonry are in hardscape. Decorative basin and recirculation equipment are in the water-feature package. Drainage and irrigation distribution are in Raincraft. Furniture covers loose items; the pavilion kitchen is optional. Lighting supply, installation and controls are in Afterglow Gardens. The first-year care allowance is separate from initial planting.</p><h2>Not included</h2><p>Property purchase, house construction or renovation, measured surveys, planning or permit fees, specialist structural/electrical/hydraulic engineering, exceptional remediation, utility diversions and unapproved scope changes. Water-feature safety and accessibility must be resolved during technical design. This concept does not make compliance or horticultural suitability claims.</p><h2>Plans, plants and imagery</h2><p>The assumed 40 × 35 m plot is illustrative. All four plans are schematic, not surveyed or construction-ready. Plant candidates, quantities, light positions, drainage and levels require site review. All images are AI-generated concepts. The aerial view establishes atmosphere; the masterplan defines conceptual adjacency. The kitchen imagery includes an optional upgrade.</p><h2>Next decisions</h2><p>Approve the spatial concept and material direction; commission site assessment; review samples and planting candidates; select options; then coordinate technical design and procurement. The 24-week programme and all lead times are fictional planning assumptions.</p><footer>STILLWATER GARDEN / DEMO 02 / No purchase, client approval, supplier acceptance or construction instruction is represented.</footer>'''
(OUT/'scope.html').write_text(document('Stillwater Garden / Scope & assumptions',scope))
index='<div class="tag">Stillwater Garden / Project library</div><h1>The whole garden, together.</h1><div class="banner">Fictional demonstration. All 15 supplier documents and all costs are invented.</div><p><a href="index.html">Presentation</a> · <a href="Stillwater-Garden-Presentation.pdf">PDF deck</a> · <a href="budget.csv">Budget</a> · <a href="materials.csv">Materials</a> · <a href="planting.csv">Planting schedule</a> · <a href="programme.csv">Programme</a> · <a href="scope.pdf">Scope PDF</a></p><table><tr><th>Document</th><th>Supplier</th><th>Relationship</th></tr>'
for q in quotes:
    r=next(x for x in budget if x['key']==q[3]);rel='Included subquote' if r['included'] else 'Optional additional' if r['optional'] else 'Allowance' if r['kind']=='estimate' else 'Top-level package'
    index+=f'<tr><td><a href="suppliers/{q[0]}.pdf">{q[0]} PDF</a> · <a href="suppliers/{q[0]}.html">HTML</a></td><td>{q[1]}</td><td>{rel}</td></tr>'
(OUT/'supplier-index.html').write_text(document('Stillwater Garden / Project pack',index+'</table>'))
print(f'Built {len(slides)} slides, 4 vector design plans, {len(quotes)} supplier quotes and {len(budget)} budget rows.')
